          "subject": "math",
          "chapter": "geometry",
          "topic": "Parallel Lines and a Transversal",
          "conceptId": "math_geometry_parallel_lines_and_a_transversal",
          "skillId": "math_geometry",
          "subskillId": "math_geometry_q1"
