          "hint": "Multiply 12 by 12.",
          "subject": "math",
          "chapter": "geometry",
          "topic": "Area of a Square",
          "conceptId": "math_geometry_area_of_a_square",
          "skillId": "math_geometry",
          "subskillId": "math_geometry_q1"
